```javascript
class Example extends Phaser.Scene {
  create () {
    const player = this.add.rectangle(320, 300, 20, 20, 0xff4444);
    const cursors = this.input.keyboard.createCursorKeys();
    this.events.on('update', () => {
      if (cursors.left.isDown)  player.x -= 7;
      if (cursors.right.isDown) player.x += 7;
      if (cursors.up.isDown)    player.y -= 7;
      if (cursors.down.isDown)  player.y += 7;
      player.x = Phaser.Math.Clamp(player.x, 10, 630);
      player.y = Phaser.Math.Clamp(player.y, 10, 590);
    });
  }
}
new Phaser.Game({ type: Phaser.AUTO, width: 640, height: 600, backgroundColor: '#1a1a2e', scene: Example });
```

```javascript
class Example extends Phaser.Scene {
  create () {
    const ground = this.add.rectangle(480, 580, 960, 20, 0x555577);
    this.physics.add.existing(ground, true);
    const box = this.add.rectangle(480, 53, 21, 21, 0x44ff88);
    this.physics.add.existing(box);
    box.body.setBounce(0.5);
    this.physics.add.collider(box, ground);
  }
}
new Phaser.Game({ type: Phaser.AUTO, width: 960, height: 600, backgroundColor: '#1a1a2e',
  physics: { default: 'arcade', arcade: { gravity: { y: 600 } } }, scene: Example });
