class Example extends Phaser.Scene {
  create () {
    let hp = 170;
    this.add.rectangle(20, 20, 121, 18, 0x333344).setOrigin(0, 0);
    const fill = this.add.rectangle(20, 20, 121, 18, 0xff4444).setOrigin(0, 0);
    const label = this.add.text(20, 44, 'HP: ' + hp, { fontSize: '16px', color: '#ffffff' });
    this.time.addEvent({ delay: 200, loop: true, callback: () => {
      hp = Math.max(0, hp - 8);
      fill.width = 121 * (hp / 170);
      label.setText('HP: ' + hp);
    }});
  }
}
